import type { Meta } from '@storybook/react-vite'
import { Select } from '../components/Select'

// A member of a named import: Storybook's own resolver reads only a member of `import * as`.
const meta = { component: Select.Option } satisfies Meta<typeof Select.Option>
export default meta
import type { Meta, StoryObj } from '@storybook/react-vite'
import { List, ListItem } from '../components/List'

/** Lists of things. */
const meta = { component: List, subcomponents: { ListItem } } satisfies Meta<typeof List>
export default meta

export const Basic: StoryObj<typeof meta> = { args: { ordered: true } }
import type { Meta, StoryObj } from '@storybook/react-vite'
import Card from '../components/Card'

const meta = { component: Card } satisfies Meta<typeof Card>
export default meta

export const Basic: StoryObj<typeof meta> = { args: { title: 'Hello' } }
